SELECT CASE WHEN d.budget >= 3673000 THEN 'high' WHEN d.budget >= 1588000 THEN 'mid' ELSE 'low' END AS budget_bucket, d.location, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(e.level))) AS level_values, ROUND(AVG(e.salary), 2) AS avg_salary FROM employees e INNER JOIN departments d ON e.dept_id = d.id WHERE LENGTH(e.email) >= 5 GROUP BY CASE WHEN d.budget >= 3673000 THEN 'high' WHEN d.budget >= 1588000 THEN 'mid' ELSE 'low' END, d.location HAVING avg_salary > 22 ORDER BY avg_salary, budget_bucket, location LIMIT 5;
